import {minute16Assets,minute16Scenes,minute16Defaults,minute16Duration,preloadMinute16,paintMinute16,validateMinute16,minute16Time,minute16MediaMetadata} from './minute16-sequence.js';
const $=id=>document.getElementById(id),stage=$('stage'),c=stage.getContext('2d',{alpha:false});
let cfg=structuredClone(minute16Defaults),time=13.2,playing=false,last=0,media={},files=[];
const fmt=t=>`16:${(Math.floor(t)).toString().padStart(2,'0')}.${((t%1)*10|0)}`;
preloadMinute16();
const archive=document.createElement('video');archive.src='./assets/minute16/archive-1600-1613-reference-only.mp4';archive.muted=true;archive.playsInline=true;archive.preload='auto';media.archive=archive;archive.addEventListener('seeked',()=>draw());archive.addEventListener('loadeddata',()=>draw());
const status=msg=>$('status').textContent=msg;
function draw(){
 const videoTime=minute16Time(time,cfg).canonical;if(videoTime<5.67&&archive.readyState>=2&&!archive.seeking&&Math.abs(archive.currentTime-videoTime)>.025)archive.currentTime=videoTime;
 const out=paintMinute16(c,time,media,cfg);
 $('timeSlider').value=time;$('timeLabel').textContent=fmt(out.referenceSecond-960);
 const scene=minute16Scenes.find(s=>s.id===out.scene);
 $('sceneLabel').textContent=(scene?.label||out.scene)+` · original ${fmt(out.referenceSecond-960)} · native 960 × 540`;
 $('scene').value=scene?.id||'confrontation';
}
function tick(now){if(playing){if(last)time=Math.min(60,Math.max(0,time+(now-last)/1000*parseFloat($('playbackSpeed').value)));if(time===60){playing=false;$('play').textContent='▶ Play'}draw()}last=now;requestAnimationFrame(tick)}requestAnimationFrame(tick);
$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ Pause':'▶ Play';if(time===60)time=0;last=0};
$('reverse').onclick=()=>{cfg.reverse=!cfg.reverse;$('reverse').textContent=cfg.reverse?'← Reversed':'↔ Reverse';status(cfg.reverse?'Playing in reverse':'Forward playback')};
$('timeSlider').oninput=e=>{time=parseFloat(e.target.value);playing=false;$('play').textContent='▶ Play';draw()};
$('frame').onclick=()=>stage.toBlob(b=>downloadBlob(b,'regaarder-minute16-'+fmt(time).replace(':','-')+'.png'),'image/png');
const downloadBlob=(b,name)=>{const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)};
function numberControl(host,name,path,min,max,step){
 const parent=document.createElement('div');parent.className='control';const lab=document.createElement('label');lab.textContent=name;
 const pair=document.createElement('div');pair.className='pair';const slider=document.createElement('input');slider.type='range';slider.min=min;slider.max=max;slider.step=step;slider.value=path.get();const val=document.createElement('input');val.type='number';val.min=min;val.max=max;val.step=step;val.value=path.get();val.setAttribute('aria-label',name);val.style.width='78px';
 const update=v=>{if(!Number.isFinite(v))return;v=Math.max(min,Math.min(max,v));path.set(v);slider.value=v;val.value=v;draw()};slider.oninput=()=>update(+slider.value);val.onchange=()=>update(+val.value);pair.append(slider,val);parent.append(lab,pair);host.append(parent)
}
function mainControls(){const host=$('globals');host.replaceChildren();for(const [name,key,min,max,step] of [['Scene timing speed','speed',.1,3,.05],['Ambient light','ambientStrength',0,1.5,.01],['Camera dolly','cameraDolly',0,1.8,.01],['Depth / parallax','parallax',.3,2,.02],['Glow','glow',0,2,.02],['Zoom','zoomScale',.5,2,.01],['Film grain','grain',0,.20,.01],['Falling particles','snow',0,1,.01],['Water speed','waterSpeed',0,40,1],['Water texture','waterStrength',0,2,.05],['Water reflections','reflection',0,2,.05],['Atmospheric mist','mist',0,2,.05],['Ship glow','shipBloom',0,3,.05],['Shoe rocking','shoeTilt',0,6,.1],['Hand motion','handMotion',0,2,.05],['Money glow','moneyGlow',0,2,.05],['Money blur','moneyBlur',0,8,.1],['Group movement','photoParallax',0,2,.05],['Photo starting size','photoStartScale',1,2,.01],['Photo ending size','photoEndScale',1,2,.01],['Shoe rise starts','shoeEntryStart',45,48,.05],['Shoe rise ends','shoeEntryEnd',48,50,.05],['Shoe retreat starts','shoeExitStart',54,56,.05],['Shoe retreat ends','shoeExitEnd',56,57,.05]])numberControl(host,name,{get:()=>cfg[key],set:v=>cfg[key]=v},min,max,step);const checks=document.createElement('div');checks.className='control';for(const [key,label] of [['occlusion','Foreground occlusion'],['brandLabels','Ship labels'],['showBounds','Debug bounds']]){const check=document.createElement('label');const box=document.createElement('input');box.type='checkbox';box.checked=cfg[key];box.onchange=()=>{cfg[key]=box.checked;draw()};check.append(box,' '+label);checks.append(check)}host.append(checks);for(const id of ['blue','orange']){const row=document.createElement('label');row.className='control';row.textContent=id+' ship label';const input=document.createElement('input');input.type='text';input.value=cfg.brandText[id];input.onchange=()=>{cfg.brandText[id]=input.value;draw()};row.append(input);host.append(row)}}
function assetInputs(){const host=$('assets');host.replaceChildren();const row=document.createElement('div');row.className='control';row.textContent='Opening archival video · existing clip · 0–5.67s';const vf=document.createElement('input');vf.type='file';vf.accept='video/*';vf.onchange=()=>{if(vf.files?.[0]){const u=URL.createObjectURL(vf.files[0]);files.push(u);archive.src=u;status('Archival video replaced for this session')}};row.append(vf);host.append(row);for(const [id,path] of Object.entries(minute16Assets).filter(([id])=>!['captain','rightPlayer','foregroundFan','celebration'].includes(id))){const el=document.createElement('div');el.className='control';const lab=document.createElement('label');lab.textContent=id+' · '+path+' · '+minute16MediaMetadata[id].kind;const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.onchange=()=>{if(!file.files?.[0])return;let img=new Image(),url=URL.createObjectURL(file.files[0]);img.onload=()=>{media[id]=img;draw()};img.src=url;files.push(url);status('Replaced '+id+' (session only; keep/download your preset and copy new asset into project for permanent storage).')};el.append(lab,file);host.append(el)}}

function layers(){const select=$('layer');select.replaceChildren();for(const id of Object.keys(minute16Assets).filter(id=>!['captain','rightPlayer','foregroundFan','celebration'].includes(id))){const opt=new Option(id==='celebrationGroup'?'Celebration · combined group':id,id);select.append(opt)}select.value='boot';select.onchange=layerControls;layerControls()}
function layerControls(){const id=$('layer').value,host=$('layerControls');host.replaceChildren();cfg.layers[id]??={...minute16Defaults.layers[id]};const l=cfg.layers[id];if(id in cfg.reveals)numberControl(host,'Layer appears at (minute seconds)',{get:()=>cfg.reveals[id],set:v=>cfg.reveals[id]=v},13,23,.1);for(const [name,key,min,max,step] of [['Left/right (px)','x',-500,500,1],['Up/down (px)','y',-400,400,1],['Scale multiplier','scale',.1,3,.01],['Rotation (degrees)','rotation',-180,180,1],['Opacity','opacity',0,1,.01],['Blur (px)','blur',0,20,.1],['Depth factor','depth',.1,5,.01]])numberControl(host,name,{get:()=>l[key]??0,set:v=>l[key]=v},min,max,step);const el=document.createElement('div');el.className='control';let ch=document.createElement('input');ch.type='checkbox';ch.checked=l.visible!==false;ch.onchange=()=>{l.visible=ch.checked;draw()};const label=document.createElement('label');label.append(ch,' Visible');el.append(label);host.append(el)}
$('resetLayer').onclick=()=>{cfg.layers[$('layer').value]={...minute16Defaults.layers[$('layer').value]};layerControls();draw()};
$('downloadPreset').onclick=()=>{validateMinute16(cfg);downloadBlob(new Blob([JSON.stringify(cfg,null,2)],{type:'application/json'}),'regaarder-minute16-settings.json')};
$('loadPresetButton').onclick=()=>$('loadPreset').click();
$('loadPreset').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(v.schema!=='regaarder-minute16-v1')throw Error('Wrong preset schema');validateMinute16(v);if((v.version??121)<123)v.photoDebug='composite';if((v.version??121)<122){v.photoStartScale=1;v.photoEndScale=1}cfg={...structuredClone(minute16Defaults),...v,fit:{...minute16Defaults.fit,...v.fit},brandText:{...minute16Defaults.brandText,...v.brandText},reveals:{...minute16Defaults.reveals,...v.reveals}};mainControls();layerControls();draw();extraControls();status('Preset imported')}catch(e){status('Import error: '+e.message)}};
const sceneSelect=$('scene');for(const s of minute16Scenes)sceneSelect.append(new Option(`${fmt(s.start)} – ${s.label}`,s.id));sceneSelect.onchange=()=>{time=cfg.boundaries.find(s=>s.id===sceneSelect.value).start+.15;extraControls();draw()};
function extraControls(){
 let host=$('extraControls');if(!host){host=document.createElement('div');host.id='extraControls';$('globals').after(host)}host.replaceChildren();let h=document.createElement('h2');h.textContent='Framing calibration';host.append(h);
 for(const [name,key,min,max,step] of [['Showroom pullback','stageRetreat',0,6,.05],['Showroom shoe size','stageBootWidth',40,220,1],['Ship height','shipHeight',100,500,1],['Ship separation','shipGap',70,350,1],['Warehouse approach','warehousePush',.7,2,.01],['Observer size','observerWidth',250,900,1],['Profile size','profileWidth',300,900,1]])numberControl(host,name,{get:()=>cfg.fit[key],set:v=>cfg.fit[key]=v},min,max,step);
 h=document.createElement('h2');h.textContent='Scene timing (minute seconds)';host.append(h);const i=minute16Scenes.findIndex(s=>s.id===$('scene').value),b=cfg.boundaries[i<0?0:i],idx=i<0?0:i;
 if(idx>0)numberControl(host,'Scene starts', {get:()=>b.start,set:v=>{b.start=v;cfg.boundaries[idx-1].end=v;extraControls()}},cfg.boundaries[idx-1].start+.1,b.end-.1,.1);
 if(idx<5)numberControl(host,'Scene ends',{get:()=>b.end,set:v=>{b.end=v;cfg.boundaries[idx+1].start=v;extraControls()}},b.start+.1,cfg.boundaries[idx+1].end-.1,.1);
 h=document.createElement('h2');h.textContent='Individual pointing hands';host.append(h);let sel=document.createElement('select');for(let j=0;j<cfg.hands.length;j++)sel.append(new Option('Hand '+(j+1)+' · '+cfg.hands[j].asset,j));host.append(sel);let panel=document.createElement('div');host.append(panel);const render=()=>{panel.replaceChildren();const hand=cfg.hands[+sel.value];for(const[name,key,min,max,step]of [['Entrance','start',46,56,.1],['Horizontal','x',-200,1160,1],['Vertical','y',-200,740,1],['Size','w',100,650,1],['Angle','angle',-180,180,1],['Travel X','fromX',-600,600,1],['Travel Y','fromY',-600,600,1],['Depth','depth',.1,2,.05]])numberControl(panel,name,{get:()=>hand[key],set:v=>hand[key]=v},min,max,step)};sel.onchange=render;render();
}
mainControls();assetInputs();layers();draw();extraControls();const debug=document.createElement('select');debug.setAttribute('aria-label','Celebration layer view');for(const[id,label]of [['composite','Celebration: composite'],['background','Clean background only'],['group','Combined three-person cutout']])debug.append(new Option(label,id));debug.onchange=()=>{cfg.photoDebug=debug.value;time=7;draw()};$('globals').before(debug);
Promise.all([...preloadMinute16().values()].map(im=>im.decode().catch(()=>status('Asset unavailable: '+im.src.split('/').pop())))).then(draw);
window.minute16Editor={archive,get config(){return cfg},paint:(t)=>{time=t;draw()},get time(){return time}};
